CREATE OR REPLACE FUNCTION public.cleanup_expired_data()
 RETURNS integer
 LANGUAGE plpgsql
AS $function$
DECLARE
  deleted_count INTEGER := 0;
  temp_count INTEGER;
BEGIN
  -- Delete expired sessions
  DELETE FROM sessions WHERE expires_at < NOW();
  GET DIAGNOSTICS temp_count = ROW_COUNT;
  deleted_count := deleted_count + temp_count;

  -- Delete expired cache entries
  DELETE FROM cache WHERE expires_at IS NOT NULL AND expires_at < NOW();
  GET DIAGNOSTICS temp_count = ROW_COUNT;
  deleted_count := deleted_count + temp_count;

  -- Delete alerts older than 24 hours
  DELETE FROM dashboard_alerts WHERE created_at < NOW() - INTERVAL '24 hours';
  GET DIAGNOSTICS temp_count = ROW_COUNT;
  deleted_count := deleted_count + temp_count;

  RETURN deleted_count;
END;
$function$;

CREATE OR REPLACE FUNCTION public.get_cache(cache_key character varying)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE
  result JSONB;
BEGIN
  SELECT value INTO result
  FROM cache
  WHERE key = cache_key
    AND (expires_at IS NULL OR expires_at > NOW());
  RETURN result;
END;
$function$;

CREATE OR REPLACE FUNCTION public.set_cache(cache_key character varying, cache_value jsonb, ttl_seconds integer DEFAULT NULL::integer)
 RETURNS void
 LANGUAGE plpgsql
AS $function$
BEGIN
  INSERT INTO cache (key, value, expires_at)
  VALUES (
    cache_key,
    cache_value,
    CASE WHEN ttl_seconds IS NOT NULL THEN NOW() + (ttl_seconds || ' seconds')::INTERVAL ELSE NULL END
  )
  ON CONFLICT (key) DO UPDATE SET
    value = EXCLUDED.value,
    expires_at = EXCLUDED.expires_at,
    created_at = NOW();
END;
$function$;
